```dart
class Transaction {
  final String coinName;
  final DateTime dateTime;
  final double profitOrLoss; // positive for profit, negative for loss

  Transaction(this.coinName, this.dateTime, this.profitOrLoss);
}

class AverageProfitLoss {
  final String coinName;
  final double averageProfitLoss;
  final int numTransactions;

  AverageProfitLoss(this.coinName, this.averageProfitLoss, this.numTransactions);
}

Map<String, AverageProfitLoss> getTopCoins(List<Transaction> transactions) {
  Map<String, List<Transaction>> groupedTransactions = transactions.groupBy((txn) => txn.coinName);

  Map<String, AverageProfitLoss> result = {};

  // Calculate top 3 with highest average profit
  var maxProfitSum = 0.0;
  for (var entry in groupedTransactions.entries) {
    double avgProfitLoss = entry.value.reduce((sum, txn) => sum + txn.profitOrLoss, 0.0);
    int numTransactions = entry.value.length;

    if (avgProfitLoss > maxProfitSum || (avgProfitLoss == maxProfitSum && numTransactions < result['${entry.key}']?.numTransactions)) {
      maxProfitSum = avgProfitLoss;
      result[entry.key] = AverageProfitLoss(entry.key, avgProfitLoss / numTransactions, numTransactions);
    }

    if (result.length >= 3) break;
  }

