        output = BytesIO()
        img.save(output, format='JPEG')
        output.seek(0)

        new_key = f"resized/{image_key}"
        s3.put_object(Bucket=bucket_name_resized, Key=new_key, Body=output.getvalue())

        table.update_item(
            Key={
                'ImageKey': image_key
